mapper.select:
SELECT *
, ( CASE WHEN title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END + CASE WHEN summary LIKE CONCAT('%', #{keyword}, '%') THEN 2 ELSE 0 END + CASE WHEN content LIKE CONCAT('%', #{keyword}, '%') THEN 1 ELSE 0 END ) AS relevance_score
FROM note WHERE is_delete = 0 AND status = 'published'
AND (title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND category = #{category}
AND content_type = #{contentType}
AND author_id = #{userId}
ORDER BY is_top DESC,
relevance_score DESC, like_count DESC, view_count DESC, view_count DESC, publish_time DESC,
id DESC
